+    let file_contents = context.read_file_from_pwd(DAML_YAML)?;
+    let daml_yaml = yaml_rust::YamlLoader::load_from_str(&file_contents).ok()?;
+    let sdk_version = daml_yaml.first()?[DAML_SDK_VERSION].as_str()?;

